<article <?php post_class('story-card'); ?>><a class="story-photo" href="<?php the_permalink(); ?>"><?php if (has_post_thumbnail()) the_post_thumbnail('large', ['loading' => 'lazy']); else { ?><img src="<?php echo esc_url(fin_image('christmas-studio')); ?>" width="640" height="480" alt="" loading="lazy"><?php } ?></a><div class="card-meta"><span><?php $cats = get_the_category(); echo esc_html($cats ? $cats[0]->name : 'Journal'); ?></span><time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date('d.m.Y')); ?></time></div><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(), 26)); ?></p><a class="text-link" href="<?php the_permalink(); ?>">Read the story ↗</a></article>
